def _diagonal_values(grid, mode):
    values = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color == 0:
                continue
            index = r + c if mode == "sum" else c - r
            if index in values and values[index] != color:
                return None
            values[index] = color
    return values or None


def _axis_values(grid, axis):
    """Decode full uniform non-background rows or columns; blanks are unknown."""
    h, w = len(grid), len(grid[0])
    n = h if axis == "row" else w
    values = {}
    for i in range(n):
        line = grid[i] if axis == "row" else [grid[r][i] for r in range(h)]
        colors = set(line)
        if len(colors) == 1:
            color = next(iter(colors))
            if color:
                values[i] = color
        elif any(color != 0 for color in line):
            # A partly marked axis line is not a uniform stripe encoding.
            return None
    return values or None


def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []
    for mode in ("sum", "diff"):
        values = _diagonal_values(grid, mode)
        if values:
            fit = _periodic_pattern(values, 2 * max(h, w))
            if fit:
                p, pattern = fit
                candidates.append((len(values), len(pattern) / p, -p,
                                   mode, p, pattern))
    for mode in ("row", "col"):
        values = _axis_values(grid, mode)
        if values:
            fit = _periodic_pattern(values, 2 * max(h, w))
            if fit:
                p, pattern = fit
                candidates.append((len(values), len(pattern) / p, -p,
                                   mode, p, pattern))
    if not candidates:
        raise ValueError("no consistent stripe or diagonal encoding")
    # The valid encoding has the strongest compact, fully supported motif.
    # Tie-break on the number of observed indices and then shortest period.
    _, _, _, mode, period, pattern = max(candidates)
    if len(pattern) != period:
        raise ValueError("demonstrations do not determine every motif position")
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            index = (r + c if mode == "sum" else c - r if mode == "diff"
                     else r if mode == "row" else c)
            row.append(pattern[index % period])
        out.append(row)
    return out


